


export type DeliveryProfile = { /** Current delivery requirement and grouping policy. */ "configuration": { /** Required as a non-empty unique list when requirement is required. quote accepts shipment, pickup, and local_delivery. manual accepts digital and service. */ "allowed_types"?: Array<"shipment" | "pickup" | "local_delivery" | "digital" | "service" | (string & {})>; /** Required for quote resolution and forbidden when requirement is none or resolution_mode is manual. Controls which delivery obligations can share a choice group. */ "combination_policy"?: "combine_when_compatible" | "separate_profile" | "separate_line_item" | "fulfill_alone" | (string & {}); /** Optional physical dimensions used by quote planning. Forbidden when requirement is none or resolution_mode is manual. */ "dimensions"?: { /** Use an exact numeric string, not a floating-point number. Format: int64. */ "height": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "length": string; "unit": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "width": string; }; /** Required for quote resolution and forbidden for none or manual resolution. fixed_location requires location_id. inventory_routing forbids location_id and applies only to tracked inventory. method_origin forbids location_id. */ "origin_policy"?: { "location_id"?: string; "type": "fixed_location" | "inventory_routing" | "method_origin" | (string & {}); }; /** Whether delivery planning applies. none forbids every other configuration field. required also requires resolution_mode and allowed_types, plus the fields required by that resolution mode. */ "requirement": "none" | "required" | (string & {}); /** Required when requirement is required. quote plans physical delivery and requires origin_policy, combination_policy, and splitting_policy. manual supports digital and service items and forbids physical planning fields. */ "resolution_mode"?: "quote" | "manual" | (string & {}); /** Required for quote resolution and forbidden when requirement is none or resolution_mode is manual. Controls whether a line item quantity can be split across delivery assignments. */ "splitting_policy"?: "whole_line_item" | "quantity_split_allowed" | (string & {}); /** Optional physical weight used by quote planning. Forbidden when requirement is none or resolution_mode is manual. */ "weight"?: { /** Weight unit. Use gram, kilogram, ounce, or pound. */ "unit": "gram" | "kilogram" | "ounce" | "pound" | (string & {}); /** Use an exact numeric string, not a floating-point number. Format: int64. */ "value": string; }; }; /** Time the profile was created. Format: date-time. */ "created_at": string; /** Immutable revision used for new line-item snapshots. */ "current_delivery_profile_revision_id": string; /** Stable delivery profile ID. */ "delivery_profile_id": string; /** Read-only catalog and delivery-method compatibility diagnostics. */ "diagnostics"?: { /** Number of active delivery methods whose type is allowed by this profile. minimum: 0. */ "active_method_definitions_count": number; /** True when this is the physical catalog default and every active physical catalog obligation uses it. */ "covers_all_items": boolean; /** Number of active Locations that no active delivery method compatible with this profile can use as an origin. minimum: 0. */ "locations_without_rates_count": number; /** Up to 20 active Location IDs that no compatible active delivery method can use as an origin. Use locations_without_rates_count for the complete count. */ "unassigned_locations": Array<string>; /** True when more matching Locations exist than are returned in unassigned_locations. */ "unassigned_locations_truncated": boolean; /** Number of distinct countries explicitly named by zones referenced from compatible active delivery methods. minimum: 0. */ "zone_country_count": number; }; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Caller-owned metadata. */ "metadata"?: Record<string, string>; /** Merchant-facing profile name. */ "name": string; /** Current profile lifecycle status. */ "status": "inactive" | "active" | "archived" | "revoked" | (string & {}); /** Time the profile last changed. Format: date-time. */ "updated_at": string; /** Optimistic-concurrency version for profile writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version": string; };
